window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ebdae20a77725129"]={"versions": [{"id": "FIG-ebdae20a77725129", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzebene der ECU-Konfigurationsmetamodell-Definition) im Rahmen der AUTOSAR-Spezifikation TPS ECU Configuration. Es illustriert ein Konfigurationsbeispiel für das Gateway-Mapping unter Verwendung von Auswahlelementen (<code>EcucChoiceContainerDef</code>) und Parametercontainern (<code>EcucParamConfContainerDef</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellte Instanzen und ihre Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>ComGwMapping : EcucParamConfContainerDef</code>: Übergeordneter Container mit Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>.\n</li><li><code>ComGwSource : EcucChoiceContainerDef</code>: Sub-Container von <code>ComGwMapping</code> über Komposition <code>+subContainer</code>. Definiert eine Auswahl für die Gateway-Quelle.\n</li><li><code>ComGwDestination : EcucChoiceContainerDef</code>: Sub-Container von <code>ComGwMapping</code> über Komposition <code>+subContainer</code> mit Multiplizität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = *</code>.\n</li><li><code>ComGwSignal : EcucParamConfContainerDef</code>: Geteilte Auswahlinstanz, die sowohl für <code>ComGwSource</code> als auch für <code>ComGwDestination</code> über die Rolle <code>+choice</code> als Option zur Verfügung steht (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>).\n</li><li><code>ComGwSourceDescription : EcucParamConfContainerDef</code>: Spezifische Auswahlinstanz für <code>ComGwSource</code> über die Rolle <code>+choice</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>).\n</li><li><code>ComGwDestinationDescription : EcucParamConfContainerDef</code>: Spezifische Auswahlinstanz für <code>ComGwDestination</code> über die Rolle <code>+choice</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Objektdiagramm zur Definitionszeit der ECU-Konfiguration. Es zeigt keine zeitliche Ablaufsequenz, sondern die strukturelle Kompositions- und Verwendungslogik: Bei der Konfiguration eines konkreten <code>ComGwMapping</code> entscheidet der Integrator für <code>ComGwSource</code> bzw. <code>ComGwDestination</code>, ob als Kindelement <code>ComGwSignal</code> oder die jeweilige Beschreibung (<code>ComGwSourceDescription</code> bzw. <code>ComGwDestinationDescription</code>) gewählt wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht normativ die Wiederverwendung derselben Containerdefinition (<code>ComGwSignal</code>) als Auswahlelement (<code>+choice</code>) in mehreren unterschiedlichen Choice-Containern (<code>ComGwSource</code> und <code>ComGwDestination</code>). Validierungswerkzeuge für Konfigurationseditoren müssen sicherstellen, dass pro instanziiertem Choice-Container genau eine der definierten Choice-Alternativen gewählt wird und die jeweiligen Multiplizitätsgrenzen eingehalten werden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f08362e29a06051e", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzebene der ECU-Konfigurationsmetamodell-Definition) im Rahmen der AUTOSAR-Spezifikation TPS ECU Configuration. Es illustriert ein Konfigurationsbeispiel für das Gateway-Mapping unter Verwendung von Auswahlelementen (<code>EcucChoiceContainerDef</code>) und Parametercontainern (<code>EcucParamConfContainerDef</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellte Instanzen und ihre Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>ComGwMapping : EcucParamConfContainerDef</code>: Übergeordneter Container mit Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code> und <code>postBuildChangeable = true</code>.\n</li><li><code>ComGwSource : EcucChoiceContainerDef</code>: Sub-Container von <code>ComGwMapping</code> über Komposition <code>+subContainer</code>. Definiert eine Auswahl für die Gateway-Quelle.\n</li><li><code>ComGwDestination : EcucChoiceContainerDef</code>: Sub-Container von <code>ComGwMapping</code> über Komposition <code>+subContainer</code> mit Multiplizität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = *</code> und <code>postBuildChangeable = true</code>.\n</li><li><code>ComGwSignal : EcucParamConfContainerDef</code>: Geteilte Auswahlinstanz, die sowohl für <code>ComGwSource</code> als auch für <code>ComGwDestination</code> über die Rolle <code>+choice</code> als Option zur Verfügung steht (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>).\n</li><li><code>ComGwSourceDescription : EcucParamConfContainerDef</code>: Spezifische Auswahlinstanz für <code>ComGwSource</code> über die Rolle <code>+choice</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>).\n</li><li><code>ComGwDestinationDescription : EcucParamConfContainerDef</code>: Spezifische Auswahlinstanz für <code>ComGwDestination</code> über die Rolle <code>+choice</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Objektdiagramm zur Definitionszeit der ECU-Konfiguration. Es zeigt keine zeitliche Ablaufsequenz, sondern die strukturelle Kompositions- und Verwendungslogik: Bei der Konfiguration eines konkreten <code>ComGwMapping</code> entscheidet der Integrator für <code>ComGwSource</code> bzw. <code>ComGwDestination</code>, ob als Kindelement <code>ComGwSignal</code> oder die jeweilige Beschreibung (<code>ComGwSourceDescription</code> bzw. <code>ComGwDestinationDescription</code>) gewählt wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht normativ die Wiederverwendung derselben Containerdefinition (<code>ComGwSignal</code>) als Auswahlelement (<code>+choice</code>) in mehreren unterschiedlichen Choice-Containern (<code>ComGwSource</code> und <code>ComGwDestination</code>). Durch das Attribut <code>postBuildChangeable = true</code> an <code>ComGwMapping</code> und <code>ComGwDestination</code> ist festgelegt, dass die Konfiguration dieser Container zur Post-Build-Zeit änderbar sein kann. Validierungswerkzeuge und Codegeneratoren müssen neben der Einhaltung der Choice-Semantik und Multiplizitäten auch die Unterstützung von Post-Build-Variabilität für diese Container vorsehen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-ebdae20a77725129", "to": "FIG-f08362e29a06051e", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>ComGwMapping</code>: Attribut <code>postBuildChangeable = true</code> hinzugefügt; Reihenfolge der Multiplizitätsattribute von <code>upperMultiplicity</code>, <code>lowerMultiplicity</code> auf <code>lowerMultiplicity</code>, <code>upperMultiplicity</code> umgestellt.\n</li><li><code>ComGwDestination</code>: Attribut <code>postBuildChangeable = true</code> hinzugefügt; Reihenfolge der Multiplizitätsattribute von <code>upperMultiplicity</code>, <code>lowerMultiplicity</code> auf <code>lowerMultiplicity</code>, <code>upperMultiplicity</code> umgestellt.\n</li></ul>"}]};
